#!/usr/bin/env python3
"""Patches the platform folders generated by `flutter create` for Prompt Forge.

Idempotent: running it twice changes nothing the second time. Fails loudly (exit 1) when an expected
anchor is missing, instead of silently producing an app that cannot open a vault folder.

  python3 tool/patch_platforms.py [--signing]
"""
import plistlib
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
APP_NAME = "Prompt Forge"
failures = []


def fail(msg):
    failures.append(msg)
    print("PATCH FAILED:", msg, file=sys.stderr)


# --------------------------------------------------------------------------- Android manifest
def patch_manifest():
    p = ROOT / "android/app/src/main/AndroidManifest.xml"
    if not p.exists():
        return fail(f"{p} not found - run `flutter create` first")
    s = p.read_text(encoding="utf-8")
    perms = [
        # Scoped storage cannot give a plain-file vault (Obsidian-style) access to an arbitrary folder, so the app
        # asks for "All files access" on Android 11+ and the legacy permissions below that.
        '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32" />',
        '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="32" />',
        '<uses-permission android:name="android.permission.MANAGE_EXTERNAL_STORAGE" />',
    ]
    changed = False
    for perm in perms:
        name = re.search(r'android:name="([^"]+)"', perm).group(1)
        if name not in s:
            if "<application" not in s:
                return fail("AndroidManifest.xml has no <application> element")
            s = s.replace("<application", perm + "\n    <application", 1)
            changed = True
    if 'android:requestLegacyExternalStorage' not in s:
        s = s.replace("<application", '<application\n        android:requestLegacyExternalStorage="true"', 1)
        changed = True
    s2 = re.sub(r'android:label="[^"]*"', f'android:label="{APP_NAME}"', s, count=1)
    if s2 != s:
        s, changed = s2, True
    if changed:
        p.write_text(s, encoding="utf-8")
        print("patched", p.relative_to(ROOT))


# --------------------------------------------------------------------------- iOS Info.plist
def patch_info_plist():
    p = ROOT / "ios/Runner/Info.plist"
    if not p.exists():
        return fail(f"{p} not found - run `flutter create` first")
    with p.open("rb") as f:
        d = plistlib.load(f)
    want = {
        "CFBundleDisplayName": APP_NAME,
        # Makes the app's Documents folder (the default vault) visible in the Files app and to Obsidian/other editors.
        "UIFileSharingEnabled": True,
        "LSSupportsOpeningDocumentsInPlace": True,
    }
    changed = False
    for k, v in want.items():
        if d.get(k) != v:
            d[k] = v
            changed = True
    if changed:
        with p.open("wb") as f:
            plistlib.dump(d, f)
        print("patched", p.relative_to(ROOT))


# --------------------------------------------------------------------------- Android signing (optional)
KTS_IMPORTS = """import java.io.FileInputStream
import java.util.Properties

"""
# Gradle requires the plugins {} block to come first (only imports may precede it), so the properties
# loader is inserted right before the android {} block instead of at the top of the file.
KTS_LOADER = """val keystoreProperties = Properties().apply {
    val f = rootProject.file("key.properties")
    if (f.exists()) load(FileInputStream(f))
}

"""
KTS_SIGNING = """    signingConfigs {
        create("release") {
            if (keystoreProperties.containsKey("storeFile")) {
                keyAlias = keystoreProperties["keyAlias"] as String
                keyPassword = keystoreProperties["keyPassword"] as String
                storeFile = file(keystoreProperties["storeFile"] as String)
                storePassword = keystoreProperties["storePassword"] as String
            }
        }
    }

"""
GROOVY_LOADER = """def keystoreProperties = new Properties()
def keystorePropertiesFile = rootProject.file('key.properties')
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

"""
GROOVY_SIGNING = """    signingConfigs {
        release {
            if (keystoreProperties['storeFile']) {
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
                storeFile file(keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
            }
        }
    }

"""


def patch_signing():
    kts = ROOT / "android/app/build.gradle.kts"
    groovy = ROOT / "android/app/build.gradle"
    if kts.exists():
        s = kts.read_text(encoding="utf-8")
        if 'getByName("release")' in s and "keystoreProperties" in s:
            return
        if "buildTypes {" not in s:
            return fail("build.gradle.kts has no buildTypes block")
        if not re.search(r"^android\s*\{", s, re.M):
            return fail("build.gradle.kts has no top-level android {} block")
        s = KTS_IMPORTS + s
        s = re.sub(r"^android\s*\{", lambda m: KTS_LOADER + m.group(0), s, count=1, flags=re.M)
        s = s.replace("    buildTypes {", KTS_SIGNING + "    buildTypes {", 1)
        s, n = re.subn(r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)', 'signingConfig = if (keystoreProperties.containsKey("storeFile")) signingConfigs.getByName("release") else signingConfigs.getByName("debug")', s)
        if n == 0:
            return fail("could not find the debug signingConfig line in build.gradle.kts (Flutter template changed?)")
        kts.write_text(s, encoding="utf-8")
        print("patched", kts.relative_to(ROOT))
    elif groovy.exists():
        s = groovy.read_text(encoding="utf-8")
        if "keystoreProperties" in s:
            return
        if "buildTypes {" not in s:
            return fail("build.gradle has no buildTypes block")
        if not re.search(r"^android\s*\{", s, re.M):
            return fail("build.gradle has no top-level android {} block")
        s = re.sub(r"^android\s*\{", lambda m: GROOVY_LOADER + m.group(0), s, count=1, flags=re.M)
        s = s.replace("    buildTypes {", GROOVY_SIGNING + "    buildTypes {", 1)
        s, n = re.subn(r"signingConfig\s+signingConfigs\.debug", "signingConfig keystoreProperties['storeFile'] ? signingConfigs.release : signingConfigs.debug", s)
        if n == 0:
            return fail("could not find the debug signingConfig line in build.gradle (Flutter template changed?)")
        groovy.write_text(s, encoding="utf-8")
        print("patched", groovy.relative_to(ROOT))
    else:
        fail("no android/app/build.gradle(.kts) found")


if __name__ == "__main__":
    patch_manifest()
    patch_info_plist()
    if "--signing" in sys.argv:
        patch_signing()
    if failures:
        sys.exit(1)
    print("platform patches applied")
